<script>
import { createPage } from '@mpxjs/core'

createPage({
  data: {
    memberId: 'member-10086',
    campaignId: 'summer-sale',
    campaigns: [
      { id: 'summer-sale', name: '夏日特卖' },
      { id: 'member-day', name: '会员日' },
      { id: 'fresh-week', name: '生鲜周' }
    ],
    campaign: {
      title: '夏日清凉特卖',
      subtitle: '限时领券，爆款低至五折'
    },
    campaignUrl: 'https://campaign.example.com/summer-sale?memberId=member-10086',
    loading: true,
    errorText: '',
    trackerReady: false,
    trackerVisible: true
  },
  onLoad () {
    if (__mpx_mode__ === 'web') {
      this.pageActive = true
      this.webviewGeneration = 0
    }
  },
  onShow () {
    if (__mpx_mode__ === 'web') {
      this.pageActive = true
      this.trackerVisible = true
      if (!this.campaignUrl) {
        this.loading = true
        this.errorText = ''
        this.remountCampaign(this.campaignId)
      }
    }
  },
  onHide () {
    if (__mpx_mode__ === 'web') {
      this.deactivateCampaign()
    }
  },
  onUnload () {
    if (__mpx_mode__ === 'web') {
      this.deactivateCampaign()
    }
  },
  methods: {
    switchCampaign (campaignId) {
      if (campaignId === this.campaignId) return
      this.campaignId = campaignId
      this.loading = true
      this.errorText = ''
      if (__mpx_mode__ === 'web') {
        this.remountCampaign(campaignId)
      } else {
        this.campaignUrl = this.getCampaignUrl(campaignId)
      }
    },
    getCampaignUrl (campaignId) {
      return `https://campaign.example.com/${campaignId}?memberId=${this.memberId}`
    },
    async remountCampaign (campaignId) {
      const generation = ++this.webviewGeneration
      this.campaignUrl = ''
      await this.$nextTick()
      if (!this.pageActive || generation !== this.webviewGeneration || campaignId !== this.campaignId) return
      this.campaignUrl = this.getCampaignUrl(campaignId)
    },
    deactivateCampaign () {
      if (!this.pageActive) return
      this.pageActive = false
      this.webviewGeneration++
      this.campaignUrl = ''
      this.trackerVisible = false
    },
    handleCampaignLoad () {
      if (__mpx_mode__ === 'web' && (!this.pageActive || !this.campaignUrl)) return
      this.loading = false
      wx.reportAnalytics('campaign_webview_load', {
        campaign_id: this.campaignId
      })
    },
    handleCampaignError () {
      if (__mpx_mode__ === 'web' && (!this.pageActive || !this.campaignUrl)) return
      this.loading = false
      this.errorText = '活动会场暂时无法打开'
    },
    handleCampaignMessage (event) {
      const data = event.detail.data || []
      const message = Array.isArray(data) ? data[data.length - 1] || {} : data
      if (__mpx_mode__ === 'web' && message.campaignId !== this.campaignId) return
      if (message.type === 'claim-coupon') {
        this.claimCoupon(message.couponId)
      }
      if (message.type === 'open-product') {
        this.openProduct(message.productId)
      }
      if (message.type === 'campaign-exposure') {
        const tracker = this.selectComponent('#campaign-tracker')
        if (tracker) tracker.trackExposure(message.payload)
      }
    },
    claimCoupon (couponId) {
      wx.request({
        url: '/api/campaign/coupons/claim',
        method: 'POST',
        data: { campaignId: this.campaignId, couponId },
        success: () => {
          wx.showToast({ title: '领取成功', icon: 'success' })
        }
      })
    },
    openProduct (productId) {
      wx.navigateTo({
        url: `/packageProduct/pages/detail/index?id=${productId}&campaignId=${this.campaignId}`
      })
    },
    reloadCampaign () {
      this.loading = true
      this.errorText = ''
      if (__mpx_mode__ === 'web') {
        this.remountCampaign(this.campaignId)
      } else {
        const campaignUrl = this.campaignUrl
        this.campaignUrl = ''
        this.campaignUrl = campaignUrl
      }
    },
    handleTrackerReady () {
      this.trackerReady = true
    },
    handleTrackerError () {
      this.trackerReady = false
    }
  }
})
</script>

